def W(s): return re.sub(r"\{([^}]*)\}", lambda m: "⁦" + m.group(1) + "⁩", s)
def O(o): o = W(o); return o if re.search(r"[֐-׿]", o) or o.startswith("⁦") else "⁦" + o + "⁩"
def Q(topic, q, opts, ans, expl, sc): return (topic, W(q), [O(o) for o in opts], ans, W(expl), sc)

_TXT = TXT
def TXT(*lines, s=None):                                                # number cards as big as the frame allows
    return _TXT(*lines, s=s or min(32, 70 / len(lines), 230 / max(len(l) for l in lines)))
def PAIR(a, b, s=40): return [(a, 30, 52, s), (b, 70, 52, s)]
def PT(e, *lines):
    """The object above, the given numbers below it (a card)."""
    n = len(lines); z = min(20, 15 if n > 1 else 20, 140 / max(len(l) for l in lines))
    if n == 1: return [(e, 50, 30, 38), (lines[0], 50, 76, round(z))]
    return [(e, 50, 24, 32)] + [(l, 50, round(50 + 42 * (i + .5) / n, 1), round(z)) for i, l in enumerate(lines)]
def CARD(*lines, e=None):
    """Hebrew text on cards, one line under the other; an emoji in the corner."""
    n = len(lines); s = round(min(15, 160 / max(len(l) for l in lines), 12.5 if n >= 4 else 15), 1)
    ys = {1: [50], 2: [36, 64], 3: [24, 50, 76], 4: [17, 38, 59, 80]}[n]
    return ([(e, 8, 13, 16)] if e else []) + [(l, 52 if e else 50, y, s) for l, y in zip(lines, ys)]
def _w(n, s): return (n * .6 + .8) * s / 1.6
def TAB(*rows):
    """A small table, Hebrew-style: the row name on the right, the values to its left."""
    n, k = len(rows), len(rows[0]) - 1; ys = {1: [45], 2: [30, 58], 3: [20, 43, 66]}[n]
    hl, vl = max(len(r[0]) for r in rows), max(len(v) for r in rows for v in r[1:])
    for s in range(15, 9, -1):
        hw, vw = _w(hl, s), _w(vl, s); step = vw + 2.5; total = hw + 3 + step * (k - 1) + vw
        if total <= 95: break
    right = 50 + total / 2; hx = right - hw / 2; x0 = right - hw - 3 - vw / 2
    out = []
    for r, y in zip(rows, ys):
        out.append((r[0], round(hx, 1), y, s))
        out += [(v, round(x0 - i * step, 1), y, s) for i, v in enumerate(r[1:])]
    return out
def BARS(note, *rows):
    """A bar graph lying on its side, Hebrew-style: the name on the right, the bar (█ blocks) growing to the left; the key below."""
    n = len(rows); ys = [round(12 + 66 * (i + .5) / n, 1) for i in range(n)]; s = 12
    hl = max(len(r[0]) for r in rows); hw = _w(hl, s); right = 96; hx = right - hw / 2; bx = right - hw - 3
    out = []
    for (name, k), y in zip(rows, ys):
        bw = _w(k, s); out += [(name, round(hx, 1), y, s), ("█" * k, round(bx - bw / 2, 1), y, s)]
    return out + [(note, 50, 90, 10)]
def LINE(xname, yname, xs, ys):
    """A line graph: each point is drawn as its value, at its height; the x values under them; the axis names."""
    lo, hi, k = min(ys), max(ys), len(xs)
    nw = _w(len(xname), 11); nx = 98.5 - nw / 2; right = min(76, nx - nw / 2 - 7 - _w(max(len(str(v)) for v in xs), 10) / 2)
    px = [14 + i * (right - 14) / (k - 1) for i in range(k)]
    py = [48 if hi == lo else 72 - (y - lo) / (hi - lo) * 48 for y in ys]
    out = [(str(v), round(x, 1), round(y, 1), 12) for v, x, y in zip(ys, px, py)]
    out += [(str(v), round(x, 1), 90, 10) for v, x in zip(xs, px)]
    return out + [(yname, round(2 + _w(len(yname), 11) / 2, 1), 9, 11), (xname, round(nx, 1), 90, 11)]

